"""Fail closed on changes to the bounded self-hosted validation contract."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
WORKFLOW = ROOT / ".github/workflows/self-hosted-validation.yml"
EXPECTED = 'name: AI-powered IaaP self-hosted validation\n\non:\n  repository_dispatch:\n    types: [ghe04-self-hosted-validation]\n\npermissions:\n  contents: read\n\njobs:\n  validate:\n    runs-on: [self-hosted, linux, x64, iaap-accelerator-ghe04]\n    timeout-minutes: 30\n    env:\n      BASH_ENV: \'\'\n      SHELLOPTS: \'\'\n      BASHOPTS: \'\'\n      PYTHONPATH: \'\'\n      PYTHONHOME: \'\'\n      PYTHONSTARTUP: \'\'\n      PYTHONUSERBASE: \'\'\n      PYTHONINSPECT: \'\'\n      MAKEFLAGS: \'\'\n      GNUMAKEFLAGS: \'\'\n      MAKEFILES: \'\'\n      PIP_TARGET: \'\'\n      PIP_PREFIX: \'\'\n      PIP_USER: \'\'\n      PIP_REQUIRE_VIRTUALENV: \'\'\n      PIP_CONFIG_FILE: /dev/null\n      PATH: /usr/bin:/bin\n    steps:\n      - name: Checkout immutable dispatch commit\n        timeout-minutes: 2\n        uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683\n        with:\n          ref: ${{ github.sha }}\n          persist-credentials: false\n      - name: Run bounded AI-powered IaaP validation\n        timeout-minutes: 20\n        shell: /usr/bin/bash --noprofile --norc -euo pipefail {0}\n        run: |\n          /usr/bin/python3 -I - <<\'PYTHON\'\n          import platform, struct, sys\n          if platform.python_implementation() != \'CPython\' or sys.version_info[:2] != (3, 12):\n              raise SystemExit(\'CPython 3.12 required\')\n          if platform.system() != \'Linux\' or platform.machine() not in {\'x86_64\', \'AMD64\'} or struct.calcsize(\'P\') * 8 != 64:\n              raise SystemExit(\'64-bit Linux x64 CPython required\')\n          PYTHON\n          /usr/bin/python3 -E -s scripts/validate_self_hosted_workflow.py\n          /usr/bin/bash --noprofile --norc -euo pipefail scripts/validate-modern-accelerator.sh\n          /usr/bin/python3 -E -s scripts/verify_portfolio_provenance.py\n          /usr/bin/python3 -E -s -m unittest discover -s tests -p \'test_*.py\'\n          /usr/bin/python3 -E -s scripts/validate_self_hosted_evidence.py\n          # Keep installed documentation dependencies and build output outside source scans.\n          [[ "${RUNNER_TEMP:?}" = /* ]]\n          [[ "${GITHUB_RUN_ID:?}" =~ ^[0-9]+$ ]]\n          [[ "${GITHUB_RUN_ATTEMPT:?}" =~ ^[0-9]+$ ]]\n          job_root="$RUNNER_TEMP/iaap-accelerator-ghe04-$GITHUB_RUN_ID-$GITHUB_RUN_ATTEMPT"\n          /usr/bin/rm -rf -- "$job_root"\n          /usr/bin/python3 -I -m venv "$job_root/venv"\n          "$job_root/venv/bin/python" -I -m pip --isolated install --disable-pip-version-check --no-input -r requirements-docs.txt\n          "$job_root/venv/bin/python" -E -s -m mkdocs build --strict --site-dir "$job_root/site"\n      - name: Remove job-local documentation environment\n        timeout-minutes: 5\n        if: always()\n        shell: /usr/bin/bash --noprofile --norc -euo pipefail {0}\n        run: |\n          [[ "${RUNNER_TEMP:?}" = /* ]]\n          [[ "${GITHUB_RUN_ID:?}" =~ ^[0-9]+$ ]]\n          [[ "${GITHUB_RUN_ATTEMPT:?}" =~ ^[0-9]+$ ]]\n          /usr/bin/rm -rf -- "$RUNNER_TEMP/iaap-accelerator-ghe04-$GITHUB_RUN_ID-$GITHUB_RUN_ATTEMPT"\n'

def main():
    if WORKFLOW.read_bytes() != EXPECTED.encode("utf-8"):
        raise SystemExit("Self-hosted workflow drifted from the bounded GHE-04 contract")
    print("Self-hosted GHE-04 contract verified")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
